"""Read static cultural evaluation corpus runs generated by Topic 3."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from app.core.config import get_settings


def _runs_dir() -> Path:
    configured = get_settings().cultural_corpus_runs_dir.strip()
    if configured:
        return Path(configured).expanduser()
    workspace = Path(__file__).resolve().parents[6]
    return workspace / "Project_3_Cultural_Diversity_Corpus_Generation_Tool" / "framework" / "runs"


def normalize_cultural_corpus_sample(raw: dict[str, Any], run_id: str = "") -> dict[str, Any]:
    sample_id = str(raw.get("sample_id") or raw.get("id") or "").strip()
    review = raw.get("review_result") if isinstance(raw.get("review_result"), dict) else {}
    knowledge = raw.get("cultural_knowledge_points")
    knowledge_points = [str(item) for item in knowledge] if isinstance(knowledge, list) else []
    return {
        "id": sample_id,
        "fullQuestion": str(raw.get("user_query") or raw.get("background") or ""),
        "bgType": str(raw.get("background_type") or ""),
        "cues": knowledge_points,
        "inferred": str(raw.get("implied_ethnic_group") or ""),
        "category": "未保留主题",
        "ethnic": str(raw.get("implied_ethnic_group") or ""),
        "expected": str(raw.get("expected_answer") or ""),
        "generated": "",
        "knowledge": "；".join(knowledge_points),
        "cultureScore": 0,
        "semanticScore": 0,
        "integrityScore": 0,
        "wrongExample": "",
        "fixSuggestion": "",
        "improveItems": [],
        "evaluationKind": "reference_review",
        "reviewAccuracy": review.get("cultural_accuracy"),
        "reviewPassed": bool(review.get("overall_passed")),
        "difficultyLevel": str(raw.get("difficulty_level") or ""),
        "runId": run_id,
        "rubric": raw.get("scoring_rubric") if isinstance(raw.get("scoring_rubric"), dict) else {},
    }


def read_cultural_corpus_run_samples(run_dir: Path) -> list[dict[str, Any]]:
    samples_path = run_dir / "samples.jsonl"
    if not samples_path.is_file():
        return []
    samples: list[dict[str, Any]] = []
    for line in samples_path.read_text(encoding="utf-8").splitlines():
        if not line.strip():
            continue
        try:
            raw = json.loads(line)
        except json.JSONDecodeError:
            continue
        sample_id = str(raw.get("sample_id") or raw.get("id") or "").strip()
        if not sample_id:
            continue
        samples.append(normalize_cultural_corpus_sample(raw, run_dir.name))
    return samples


def _matches_filter(value: str, allowed: set[str]) -> bool:
    return not allowed or value in allowed


def get_cultural_corpus_samples(
    *,
    run_ids: list[str] | None = None,
    ethnic_groups: list[str] | None = None,
    difficulty_levels: list[str] | None = None,
    include_live_runs: bool = False,
    limit: int | None = None,
) -> list[dict[str, Any]] | None:
    runs_dir = _runs_dir()
    if not runs_dir.is_dir():
        return None

    allowed_runs = {item.strip() for item in run_ids or [] if item.strip()}
    allowed_ethnic = {item.strip() for item in ethnic_groups or [] if item.strip()}
    allowed_difficulty = {item.strip() for item in difficulty_levels or [] if item.strip()}
    samples: list[dict[str, Any]] = []
    seen_keys: set[str] = set()
    for path in sorted(runs_dir.glob("*/samples.jsonl")):
        run_id = path.parent.name
        if not include_live_runs and run_id.startswith("topic5_"):
            continue
        if allowed_runs and run_id not in allowed_runs:
            continue
        for sample in read_cultural_corpus_run_samples(path.parent):
            if not _matches_filter(str(sample.get("ethnic") or ""), allowed_ethnic):
                continue
            if not _matches_filter(str(sample.get("difficultyLevel") or ""), allowed_difficulty):
                continue
            sample_key = f"{run_id}:{sample['id']}"
            if sample_key in seen_keys:
                continue
            seen_keys.add(sample_key)
            samples.append(sample)
            if limit and len(samples) >= limit:
                return samples
    return samples
